class BridgeMicCapture extends AudioWorkletProcessor {
  process(inputs) {
    const input = inputs[0];
    if (!input || !input[0]) return true;
    const samples = input[0];
    const out = new Int16Array(samples.length);
    for (let i = 0; i < samples.length; i++) {
      let s = samples[i];
      if (s > 1) s = 1;
      else if (s < -1) s = -1;
      out[i] = s < 0 ? s * 0x8000 : s * 0x7fff;
    }
    // Transfer ownership — zero-copy move into main-thread land.
    this.port.postMessage(out, [out.buffer]);
    return true;
  }
}
registerProcessor('bridge-mic-capture', BridgeMicCapture);
